-- A WITH query run once (MATERIALIZED, or read twice) runs only as far as
-- its CTE Scans read it, as nodeCtescan.c pulls rows into the tuplestore
-- its readers share: a LIMIT leaves the later rows, and their errors,
-- unrun, and a second reader reads the stored rows before running more.
-- https://github.com/postgres/postgres/blob/REL_18_6/src/backend/executor/nodeCtescan.c
CREATE TABLE t840 (a int);
INSERT INTO t840 SELECT generate_series(1, 3000);
WITH c AS MATERIALIZED (SELECT 1 / (a - 2000) AS x FROM t840) SELECT * FROM c LIMIT 2;
WITH c AS MATERIALIZED (SELECT a, 1 / (a - 2000) AS x FROM t840) SELECT a FROM c WHERE a < 5 LIMIT 3;
WITH c AS MATERIALIZED (SELECT 1 AS x UNION ALL SELECT 1 / 0) SELECT * FROM c LIMIT 1;
WITH c AS MATERIALIZED (SELECT 1 AS x UNION ALL SELECT 1 / 0) SELECT * FROM c;
WITH c AS (SELECT a, 10 / (a - 2000) AS x FROM t840)
SELECT * FROM (SELECT a FROM c LIMIT 2) p
UNION ALL SELECT * FROM (SELECT a FROM c LIMIT 3) q;
WITH c AS (SELECT a, 10 / (a - 2000) AS x FROM t840)
SELECT * FROM (SELECT a FROM c LIMIT 2) p
UNION ALL SELECT * FROM (SELECT a FROM c LIMIT 1999) q ORDER BY 1 DESC LIMIT 1;
WITH c AS (SELECT a, 10 / (a - 2000) AS x FROM t840)
SELECT * FROM (SELECT a FROM c LIMIT 2) p
UNION ALL SELECT * FROM (SELECT a FROM c LIMIT 2000) q ORDER BY 1 DESC LIMIT 1;
WITH c AS MATERIALIZED (SELECT a FROM t840 WHERE a % 2 = 0)
SELECT a, (SELECT max(a) FROM (SELECT * FROM c LIMIT 5) z) FROM c LIMIT 3;
CREATE TABLE c840 AS WITH c AS MATERIALIZED (SELECT a, 1 / (a - 2000) AS x FROM t840) SELECT a FROM c LIMIT 2;
INSERT INTO c840 WITH c AS MATERIALIZED (SELECT a, 1 / (a - 2000) AS x FROM t840) SELECT a FROM c LIMIT 2;
SELECT * FROM c840 ORDER BY a;
CREATE SEQUENCE s840;
WITH c AS MATERIALIZED (SELECT nextval('s840') AS v FROM t840) SELECT * FROM c LIMIT 2;
SELECT currval('s840');
WITH c AS (SELECT nextval('s840') AS v FROM t840) SELECT * FROM c LIMIT 1;
SELECT currval('s840');
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
WITH c AS MATERIALIZED (SELECT a FROM t840) SELECT * FROM c LIMIT 2;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
WITH c AS MATERIALIZED (SELECT 1 AS x UNION ALL SELECT a FROM t840) SELECT * FROM c LIMIT 5;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
WITH c AS (SELECT a FROM t840)
SELECT * FROM (SELECT * FROM c LIMIT 2) p UNION ALL SELECT * FROM (SELECT * FROM c LIMIT 4) q;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
WITH c AS MATERIALIZED (SELECT a FROM t840) SELECT * FROM c WHERE a > 2990;
